WITH lines AS (SELECT id, service, latency_ms, status_code, key, v FROM app_logs LATERAL VIEW OUTER EXPLODE(context) li AS key, v), unpacked AS (SELECT latency_ms, status_code, v, SHIFTRIGHT(status_code, 2) AS status_code_high, CAST((status_code & 1) != 0 AS INT) AS has_fault FROM lines), base AS (SELECT latency_ms, status_code, status_code_high, latency_ms / NULLIF(has_fault, 0) AS latency_ms_per_has_fault, status_code_high + status_code AS status_code_high_plus_status_code FROM unpacked WHERE status_code >= 271), daily AS (SELECT CASE WHEN status_code_high_plus_status_code >= 85 THEN 'LARGE' ELSE 'SMALL' END AS status_code_high_plus_status_code_tier, MAX(status_code_high) AS max_status_code_high, ROUND(AVG(latency_ms), 2) AS avg_latency_ms, BIT_OR(latency_ms) AS latency_ms_bit_or, BIT_AND(latency_ms) AS latency_ms_bit_and, MAX(latency_ms_per_has_fault) AS max_latency_ms_per_has_fault FROM base GROUP BY CASE WHEN status_code_high_plus_status_code >= 85 THEN 'LARGE' ELSE 'SMALL' END) SELECT status_code_high_plus_status_code_tier, avg_latency_ms, latency_ms_bit_or, max_latency_ms_per_has_fault FROM daily ORDER BY max_latency_ms_per_has_fault, status_code_high_plus_status_code_tier LIMIT 10;
